import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetTime{Time: 12000}
POSITIVE = bytes.fromhex("c0bb01")

# generated by gophertunnel b8bd735:
# &packet.SetTime{Time: -1}
NEGATIVE = bytes.fromhex("01")

GOLDENS = [
    pytest.param(v2225.SetTimePacket(time=12000), POSITIVE, id="positive"),
    pytest.param(v2225.SetTimePacket(time=-1), NEGATIVE, id="negative"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_time_is_packet_10(version):
    assert version.PACKETS[10] is version.SetTimePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_time_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_time_decodes_from_its_golden(packet, golden):
    assert v2225.SetTimePacket.from_bytes(golden) == packet
